/* ================= Vicky Cervantes — the agent with a client ================= */
const vicky=[
 ()=>{MEET('p5_vicky');return sc(t(`名片`,`The business card`,`O cartão de visita`),STAGE(1,3),[
  t(`一个穿着米色西装、踩着高跟鞋的女人在你店里点了一杯咖啡，没喝，先递过来一张烫金名片：维多利亚·塞万提斯，房产经纪。“我有一位客户，对你店后面那块空地很感兴趣。价钱好商量。”`,`A woman in a beige suit and heels orders a coffee, doesn't drink it, and first hands you an embossed business card: Victoria Cervantes, Realtor. "I have a client who's very interested in the empty lot behind your shop. The price is negotiable."`,`Uma mulher de fato bege e saltos altos pede um café, não lhe toca, e primeiro estende-te um cartão em relevo: Victoria Cervantes, agente imobiliária. «Tenho um cliente muito interessado no terreno vazio atrás do teu restaurante. O preço é negociável.»`),
  t(`她的西班牙语带着圣安东尼奥的腔调，英语像电视新闻。“叫我维姬就行。大家都叫我维姬。”`,`Her Spanish has a San Antonio lilt; her English sounds like the evening news. "Call me Vicky. Everybody does."`,`O espanhol dela tem a cadência de San Antonio; o inglês parece o telejornal. «Chama-me Vicky. Toda a gente chama.»`)],[
  {t:t(`礼貌地拒绝：这块地不卖`,`Politely decline: the lot isn't for sale`,`Recusar com educação: o terreno não está à venda`),fx:()=>{addTrust('p5_vicky',1);stat('tex',1)},
   next:out(t(`她把名片留在柜台上：“想法会变的。我的电话一直开着。”出门前她回头看了一眼你墙上若泽的照片，看了很久。`,`She leaves the card on the counter. "Minds change. My phone's always on." On her way out she looks back at José's photo on your wall, for a long time.`,`Deixa o cartão no balcão. «As pessoas mudam de ideias. O meu telefone está sempre ligado.» À saída, olha para trás, para a fotografia do José na parede, durante muito tempo.`),SUM(`维姬信任 +1 · 德州味 +1`,`Vicky trust +1 · Texanness +1`,`Confiança da Vicky +1 · Texanidade +1`))},
  {t:t(`问她：您的客户是谁？`,`Ask: who's your client?`,`Perguntar: quem é o seu cliente?`),fx:()=>{addTrust('p5_vicky',1);S.flags.p5_vickyAsk=1},
   next:out(t(`“客户希望保密。”她笑得很职业，可是搅咖啡的勺子停了一下，“你知道的，这个镇上，有钱买地的人不多。”`,`"My client prefers to remain confidential." Her smile is perfectly professional, but her spoon stops stirring for a beat. "You know how it is. Not many people in this town can afford to buy land."`,`«O meu cliente prefere manter-se anónimo.» O sorriso é perfeitamente profissional, mas a colher para de mexer por um instante. «Sabe como é. Nesta vila não há muita gente com dinheiro para comprar terra.»`),SUM(`维姬信任 +1`,`Vicky trust +1`,`Confiança da Vicky +1`))},
  {t:t(`[魅力 45] 请她把咖啡喝了，坐下来慢慢谈`,`[Charm 45] Get her to drink the coffee and sit down for a proper talk`,`[Charme 45] Convencê-la a beber o café e a sentar-se para conversar`),req:CHARM_REQ(45),fx:()=>{addLike('p5_vicky',2);S.flags.p5_vickyAsk=1},
   next:out(t(`她喝了咖啡，还吃了一个蛋挞，说自己小时候在罐头厂旁边那条街长大。说完她好像后悔了，起身就走。`,`She drinks the coffee, eats a tart, and mentions she grew up on the street next to the cannery. Then she seems to regret saying it, and leaves.`,`Bebe o café, come um pastel e conta que cresceu na rua ao lado da fábrica. Depois parece arrepender-se de ter dito isso e vai-se embora.`),SUM(`维姬好感 +2`,`Vicky affection +2`,`Afeto da Vicky +2`))}])},
 ()=>sc(t(`她自己的那条街`,`Her own street`,`A rua dela`),STAGE(2,3),[
  t(`维姬开车带你去罐头厂东边的那条街。一排小木屋，门廊上晾着衣服，几个孩子在空地上踢一个瘪了的足球。“我在这儿长大。我妈哮喘，每年夏天都要住两次院。医生说是过敏。”`,`Vicky drives you to the street east of the cannery: a row of little wooden houses, laundry on the porches, kids kicking a flat football around an empty lot. "I grew up here. My mother had asthma; every summer she ended up in hospital twice. The doctor said it was allergies."`,`A Vicky leva-te de carro à rua a leste da fábrica: uma fila de casinhas de madeira, roupa a secar nos alpendres, miúdos a jogar com uma bola vazia num terreno baldio. «Cresci aqui. A minha mãe tinha asma; todos os verões ia parar ao hospital duas vezes. O médico dizia que eram alergias.»`),
  t(`她盯着方向盘：“我替客户买的地，有一半在这条街上。他们给的价钱，够这些人家搬去好一点的地方。我一直这么跟自己说。”`,`She stares at the steering wheel. "Half the lots I've bought for my client are on this street. What they pay is enough for these families to move somewhere better. That's what I keep telling myself."`,`Fica a olhar para o volante. «Metade dos terrenos que comprei para o meu cliente são nesta rua. O que pagam chega para estas famílias irem para um sítio melhor. É o que vou dizendo a mim mesma.»`)],[
  {t:t(`跟她讲若泽和罐头厂废水的事`,`Tell her about José and the cannery's wastewater`,`Contar-lhe do José e das águas residuais da fábrica`),req:()=>S.letters>=8||S.week>=30||NEED(t('若泽的信 8 封或第 30 周以后','8 of José\'s letters, or after week 30','8 cartas do José, ou depois da semana 30')),fx:()=>{addTrust('p5_vicky',2);S.flags.p5_vickyKnows=1},
   next:out(t(`她听完，很久没有发动车子。“过敏，”她终于说，“二十年，医生一直说是过敏。”`,`When you finish she doesn't start the car for a long time. "Allergies," she says at last. "Twenty years, the doctors kept saying allergies."`,`Quando acabas, ela fica muito tempo sem ligar o carro. «Alergias», diz por fim. «Vinte anos, os médicos sempre a dizer que eram alergias.»`),SUM(`维姬信任 +2`,`Vicky trust +2`,`Confiança da Vicky +2`))},
  {t:t(`请她去吃一顿饭，什么也不谈`,`Take her to dinner and talk about nothing`,`Levá-la a jantar e não falar de nada`),fx:()=>{addLike('p5_vicky',1);addTrust('p5_vicky',1)},
   next:out(t(`你们去了帕蒂的卷饼车。她把高跟鞋脱了，坐在马路牙子上吃了三个卷饼，说这是她这个月吃得最好的一顿。`,`You go to Patty's taco truck. She takes off her heels, sits on the curb, eats three tacos, and says it's the best meal she's had all month.`,`Vão à carrinha de tacos da Patty. Ela tira os saltos, senta-se no passeio, come três tacos e diz que é a melhor refeição do mês.`),SUM(`维姬好感 +1 · 信任 +1`,`Vicky affection +1 · trust +1`,`Afeto da Vicky +1 · confiança +1`))},
  {t:t(`“搬走对他们也许真的更好。”`,`"Maybe moving really is better for them."`,`«Talvez mudar seja mesmo melhor para eles.»`),fx:()=>{addTrust('p5_vicky',-1)},
   next:out(t(`她点点头，好像松了一口气，又好像更难过了。回去的路上，她把收音机开得很大。`,`She nods, as if relieved, or maybe sadder. On the drive back she turns the radio up loud.`,`Acena, como se aliviada, ou talvez mais triste. No regresso põe o rádio muito alto.`),SUM(`维姬信任 −1`,`Vicky trust −1`,`Confiança da Vicky −1`))}]),
 ()=>sc(t(`撤出`,`Walking away`,`Sair`),STAGE(3,3),[
  t(`维姬在打烊后敲你的后门，手里拿着一个牛皮纸袋。“孤星砂业。特拉维斯·博伊德。我替他买下的每一块地，价钱、日期、原来的主人，都在这里。”`,`Vicky knocks on your back door after closing, holding a manila envelope. "Lone Star Sand. Travis Boyd. Every lot I bought for him — price, date, previous owner — it's all in here."`,`A Vicky bate à porta das traseiras depois de fecharem, com um envelope pardo na mão. «Lone Star Sand. Travis Boyd. Cada terreno que comprei para ele — preço, data, antigo dono — está tudo aqui.»`),
  t(`“我还没想好拿它怎么办。交出去，我在这个县就别想再卖一栋房子了。”`,`"I haven't decided what to do with it. If I hand it over, I'll never sell another house in this county."`,`«Ainda não decidi o que fazer com isto. Se o entregar, nunca mais vendo uma casa neste condado.»`)],[
  {t:t(`劝她把名单交给科琳登报`,`Urge her to give the list to Colleen for the paper`,`Convencê-la a dar a lista à Colleen para o jornal`),req:()=>(ST('vicky')>=3&&rel('p5_vicky').trust>=3)||NEED(t('维姬信任 3','Vicky trust 3','Confiança da Vicky 3')),fx:()=>{S.flags.p5_vickyTurn=1;addTrust('p5_vicky',1);addTrust('colleen',1);log('维姬交出了孤星砂业的收地名单','Vicky handed over Lone Star Sand\'s list of lots','A Vicky entregou a lista de terrenos da Lone Star Sand')},
   next:out(t(`三天后，《号角报》头版登出了一张地图：罐头厂周围的每一块地都标着红色，只有一块是空白的。维姬把自己的房产经纪执照装进了一个相框，说留个纪念。`,`Three days later the Clarion's front page runs a map: every lot around the cannery marked in red, and one left blank. Vicky puts her realtor's licence in a frame "as a souvenir."`,`Três dias depois, a primeira página do Clarion publica um mapa: todos os terrenos à volta da fábrica marcados a vermelho, e um em branco. A Vicky emoldura a licença de agente imobiliária, «como recordação».`),SUM(`维姬交出了名单 · 科琳信任 +1`,`Vicky handed over the list · Colleen trust +1`,`A Vicky entregou a lista · confiança da Colleen +1`))},
  {t:t(`陪她去找格蕾丝，问清楚她会担什么风险`,`Go with her to Grace and find out what risks she'd face`,`Ir com ela à Grace saber que riscos corre`),req:()=>rel('grace').met||NEED(t('认识格蕾丝','Know Grace','Conhecer a Grace')),fx:()=>{S.flags.p5_vickyTurn=1;addTrust('p5_vicky',2);addTrust('grace',1)},
   next:out(t(`格蕾丝说，这些交易本身都合法，可它们合在一起，就是一份很清楚的计划书。维姬听完，把纸袋放在了格蕾丝的桌子上，没有再拿回去。`,`Grace says each deal is legal on its own, but together they read like a very clear business plan. Vicky listens, sets the envelope on Grace's desk, and doesn't take it back.`,`A Grace diz que cada negócio é legal por si só, mas juntos parecem um plano de negócios muito claro. A Vicky ouve, pousa o envelope na secretária da Grace e não o volta a pegar.`),SUM(`维姬交出了名单 · 维姬信任 +2 · 格蕾丝信任 +1`,`Vicky handed over the list · Vicky trust +2 · Grace trust +1`,`A Vicky entregou a lista · confiança da Vicky +2 · confiança da Grace +1`))},
  {t:t(`“这是你的饭碗，你自己决定。”`,`"It's your livelihood. Your call."`,`«É o seu ganha-pão. A decisão é sua.»`),fx:()=>{addTrust('p5_vicky',1)},
   next:out(t(`她把纸袋夹回腋下：“谢谢你没逼我。”后来你再也没听说过那个纸袋去了哪里。`,`She tucks the envelope back under her arm. "Thanks for not pushing me." You never hear where that envelope ended up.`,`Volta a pôr o envelope debaixo do braço. «Obrigada por não me pressionar.» Nunca chegas a saber para onde foi aquele envelope.`),SUM(`维姬信任 +1`,`Vicky trust +1`,`Confiança da Vicky +1`))}])
];
